const n = Number(prompt());
const itens = [];
for (let i = 0; i < n; i++) {
  const [produto, categoria, qtd, preco] = prompt().split(" ");
  itens.push({ produto, categoria, qtd: Number(qtd), preco: Number(preco) });
}

const faturamento = itens.map(it => it.qtd * it.preco).reduce((a, b) => a + b, 0);
console.log(`Faturamento: ${faturamento}`);

const porCategoria = itens.reduce((acc, it) => {
  acc[it.categoria] = (acc[it.categoria] ?? 0) + it.qtd * it.preco;
  return acc;
}, {});
console.log("Por categoria:");
Object.keys(porCategoria)
  .sort()
  .forEach(cat => console.log(`- ${cat}: ${porCategoria[cat]}`));

const top = itens.reduce((m, it) => (it.qtd > m.qtd ? it : m));
console.log(`Mais vendido: ${top.produto} (${top.qtd} unidades)`);

const caros = itens.filter(it => it.preco >= 10).map(it => it.produto);
