class ErroValidacao extends Error {
  constructor(mensagem) {
    super(mensagem);
    this.name = "ErroValidacao";
  }
}

function validar(p) {
  if (typeof p !== "object" || p === null || Array.isArray(p)) throw new ErroValidacao("não é um objeto");
  if (typeof p.item !== "string" || p.item.length === 0) throw new ErroValidacao("item inválido");
  if (!Number.isInteger(p.qtd) || p.qtd <= 0) throw new ErroValidacao("qtd inválida");
  if (!Number.isInteger(p.preco) || p.preco < 0) throw new ErroValidacao("preco inválido");
}

const n = Number(prompt());
let total = 0;
let erros = 0;
for (let i = 1; i <= n; i++) {
  const linha = prompt();
  try {
    const p = JSON.parse(linha);
    validar(p);
    const valor = p.qtd * p.preco;
    total += valor;
    console.log(`Linha ${i}: ${p.item} x${p.qtd} = ${valor}`);
  } catch (e) {
    erros++;
    if (e instanceof SyntaxError) console.log(`Linha ${i}: JSON inválido`);
    else if (e instanceof ErroValidacao) console.log(`Linha ${i}: ${e.message}`);
    else throw e;
  }
}
console.log(`Total: ${total}`);
console.log(`Erros: ${erros}`);

