function* primos() {
  const achados = [];
  for (let c = 2; ; c++) {
    let ehPrimo = true;
    for (const p of achados) {
      if (p * p > c) break;
      if (c % p === 0) {
        ehPrimo = false;
        break;
      }
    }
    if (ehPrimo) {
      achados.push(c);
      yield c;
    }
  }
}

function* pegar(gen, k) {
  if (k <= 0) return;
  for (const x of gen) {
    yield x;
    k--;
    if (k === 0) return;
  }
}

class Intervalo {
  constructor(ini, fim, passo) {
    this.ini = ini;
    this.fim = fim;
    this.passo = passo;
  }
  *[Symbol.iterator]() {
    for (let x = this.ini; x <= this.fim; x += this.passo) yield x;
  }
}

