const valores = [...new Intervalo(ini, fim, passo)];
console.log(`Intervalo: ${valores.join(" ")}`.trimEnd());
let soma = 0;
for (const x of new Intervalo(ini, fim, passo)) soma += x * x;
console.log(`Soma dos quadrados: ${soma}`);

