lessons.solution:
const PREC = { "+": 1, "-": 1, "*": 2, "/": 2, "^": 3 };

function tokenizar(texto) {
  const tokens = [];
  let i = 0;
  while (i < texto.length) {
    const c = texto[i];
    if (c >= "0" && c <= "9") {
      let j = i;
      while (j < texto.length && texto[j] >= "0" && texto[j] <= "9") j++;
      tokens.push(texto.slice(i, j));
      i = j;
    } else if (c in PREC || c === "(" || c === ")") {
      tokens.push(c);
      i++;
    } else if (c === " ") {
      i++;
    } else {
      throw new Error(`caractere inválido '${c}'`);
    }
  }
  return tokens;
}

function paraRPN(tokens) {
  const saida = [];
  const pilha = [];
  for (const t of tokens) {
    if (t in PREC) {
      while (pilha.length > 0 && pilha[pilha.length - 1] in PREC) {
        const topo = pilha[pilha.length - 1];
        if (PREC[topo] > PREC[t] || (PREC[topo] === PREC[t] && t !== "^")) saida.push(pilha.pop());
        else break;
      }
      pilha.push(t);
    } else if (t === "(") {
      pilha.push(t);
    } else if (t === ")") {
      while (pilha.length > 0 && pilha[pilha.length - 1] !== "(") saida.push(pilha.pop());
      if (pilha.length === 0) throw new Error("parênteses desbalanceados");
      pilha.pop();
    } else {
      saida.push(t);
    }
  }
  while (pilha.length > 0) {
    const op = pilha.pop();
    if (op === "(") throw new Error("parênteses desbalanceados");
    saida.push(op);
  }
  return saida;
}

function avaliar(rpn) {
  const pilha = [];
  for (const t of rpn) {
    if (t in PREC) {
      if (pilha.length < 2) throw new Error("expressão inválida");
      const b = pilha.pop();
      const a = pilha.pop();
      if (t === "+") pilha.push(a + b);
      else if (t === "-") pilha.push(a - b);
      else if (t === "*") pilha.push(a * b);
      else if (t === "^") pilha.push(a ** b);
      else {
        if (b === 0) throw new Error("divisão por zero");
        pilha.push(Math.trunc(a / b));
      }
    } else {
      pilha.push(Number(t));
    }
  }
  if (pilha.length !== 1) throw new Error("expressão inválida");
  return pilha[0];
}

const n = Number(prompt());
for (let i = 0; i < n; i++) {
  try {
    const rpn = paraRPN(tokenizar(prompt()));
    const valor = avaliar(rpn);
    console.log(`RPN: ${rpn.join(" ")}`);
    console.log(`Valor: ${valor}`);
  } catch (e) {
    console.log(`Erro: ${e.message}`);
  }
}

