const n = Number(prompt());
const coluna = new Array(n).fill(false);
const diag1 = new Array(2 * n - 1).fill(false);
const diag2 = new Array(2 * n - 1).fill(false);
const pos = [];
let total = 0;
let primeira = null;

function resolver(linha) {
  if (linha === n) {
    total++;
    if (primeira === null) primeira = [...pos];
    return;
  }
  for (let c = 0; c < n; c++) {
    if (coluna[c] || diag1[linha - c + n - 1] || diag2[linha + c]) continue;
    coluna[c] = diag1[linha - c + n - 1] = diag2[linha + c] = true;
    pos.push(c);
    resolver(linha + 1);
    pos.pop();
    coluna[c] = diag1[linha - c + n - 1] = diag2[linha + c] = false;
  }
}

resolver(0);
console.log(`Soluções: ${total}`);
if (primeira === null) {
  console.log("Nenhuma solução");
} else {
  console.log(`Colunas: ${primeira.map(c => c + 1).join(" ")}`);
  for (const c of primeira) {
    let linha = "";
    for (let j = 0; j < n; j++) linha += j === c ? "Q" : ".";
    console.log(linha);
  }
}
